"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["37707"],{54803(e,t,n){n.d(t,{Ay:()=>r,RM:()=>o});var i=n(74848),s=n(28453);let o=[];function a(e){let t={a:"a",blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"without-confidence-everything-is-nonsense",children:"Without Confidence, Everything Is Nonsense."})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"2008/1/31 15:13:08"}),"\n"]}),"\n",(0,i.jsxs)("div",{style:{color:"#009900",fontWeight:"500",fontSize:"18px"},children:[(0,i.jsx)(t.p,{children:"At 3:30, some tedious fellow is coming all the way from Dalian specifically to discuss a shell acquisition deal in the Hong Kong market. After the meeting, I'll come back and write a post with pure technical analysis of the subsequent trend. This ID's mood has already fully shifted to New Year mode\u2014the mere thought of having things to do gives me a headache."}),(0,i.jsx)(t.p,{children:"Today's market trend is entirely unsurprising. When you're following someone else's lead, that's just how it goes. So what if they cut interest rates? In fact, even for the United States, whether they cut rates or not, what's meant to die will still die. Once rate cuts trigger massive capital dumping of dollar-denominated assets, the death will be even uglier. Unfortunately, the one pool that could absorb this massive capital flight\u2014China's\u2014is precisely what's missing. Just thinking about it is depressing. Where were they when it mattered?"}),(0,i.jsx)(t.p,{children:"Economics is a specialized discipline. Those managing the economy should at least have studied economics or grown up immersed in economic circles. Otherwise, blacksmiths, ditch-diggers, dam-builders, and flatbread vendors can all have a go at economics\u2014then what kind of economics is that?"}),(0,i.jsx)(t.p,{children:"In one sentence: this round of decline probably still won't result in the stamp duty being lowered. Likely, an even more violent plunge is needed. Of course, there will be rebounds, but as long as the stamp duty doesn't come down, this ID's enthusiasm will remain in the doldrums."}),(0,i.jsx)(t.p,{children:"This year, it all depends on what changes after the March meetings. If there are none, then things will be what they'll be. This ID absolutely will not take on the business of catching falling rocks again\u2014with transaction costs this outrageous, on what grounds?"}),(0,i.jsx)(t.p,{children:"On short-term technicals, there's nothing much to say. Right now, if this 1-minute hub can't be broken upward, it'll keep stepping down. On individual stocks, many need to proactively pull back first\u2014otherwise, holding at the top lifting barbells serves no purpose."}),(0,i.jsx)(t.p,{children:"Right now, the key isn't the stock market itself, but a crisis of confidence. Here's the simplest question: why should Chinese investors endure the highest transaction costs in the entire world?"}),(0,i.jsx)(t.p,{children:"Can anyone answer this question?"}),(0,i.jsx)(t.p,{children:"This ID already stated clearly at the end of last year: the stamp duty must come down this year. No matter who it is, if you've made a mistake, you correct it. If you don't correct it, that's unacceptable."}),(0,i.jsx)(t.p,{children:"This ID isn't worried about the stock market at all right now, because there's something far more worrying\u2014if this round of economic confrontation is handled incorrectly, things far more serious than the stock market are waiting ahead."}),(0,i.jsx)(t.p,{children:"Can we handle it correctly? Sorry, this ID has no confidence."}),(0,i.jsxs)(t.p,{children:["If you're still in the mood, please read this dream of this ID's: \"",(0,i.jsx)(t.a,{href:"../poems/recorddream",children:"Retracing Du Fu's 'Ascending Heights' Rhyme, Recording a Dream"}),' 2008-01-26 10:23:21"']}),(0,i.jsx)(t.p,{children:"Heading out now, goodbye."})]})]})}function r(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(a,{...e})}):a(e)}},68507(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>c,assets:()=>l});var i=JSON.parse('{"id":"timeline/economics/havefaith","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/economics/havefaith.md","sourceDirName":"timeline/economics","slug":"/timeline/economics/havefaith","permalink":"/en/timeline/economics/havefaith","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"havefaith","title":"","hide_table_of_contents":true,"sidebar_label":"Without Confidence, Everything Is Nonsense. (2008/1/31 15:13:08)"},"sidebar":"timelineSidebar","previous":{"title":"The First Standard of a Competent Government: Don\'t Pay the Bill for America (2008/1/30 15:57:44)","permalink":"/en/timeline/economics/donotpayforamerica"},"next":{"title":"Mid-Term Technical Analysis of the Market (2008/1/31 18:44:04)","permalink":"/en/timeline/economics/mediumperiodanalysis"}}'),s=n(74848),o=n(28453),a=n(54803);let r={id:"havefaith",title:"",hide_table_of_contents:!0,sidebar_label:"Without Confidence, Everything Is Nonsense. (2008/1/31 15:13:08)"},h,l={},c=[...a.RM];function d(e){return(0,s.jsx)(a.Ay,{})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var i=n(96540);let s={},o=i.createContext(s);function a(e){let t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);